import {normalizeNeuron,normalizeConnections} from './source-data.js';
const $=s=>document.querySelector(s);
const [manifest,sample]=await Promise.all(['structure','sample'].map(async n=>{const r=await fetch(`data/${n}.json`);if(!r.ok)throw Error('数据清单加载失败');return r.json()}));
const [sourceIndex,sourceMeta,sourceConnections]=await Promise.all(['index','meta','connections'].map(async name=>{const r=await fetch('source/'+name+(name==='index'?'.json.gz':'.json'));if(!r.ok)throw Error('原站数据索引加载失败');return name==='index'?new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json():r.json()}));
const sourceLayers=new Map(),sourceRequests=new Set(),sourceErrors=new Map(),assetSet=new Set(sourceIndex.assets);
async function ensureSourceLayer(layer){if(!layer||sourceLayers.has(layer)||sourceRequests.has(layer)||sourceErrors.has(layer))return;sourceRequests.add(layer);try{const r=await fetch('source/data/'+layer+'.json.gz');if(!r.ok)throw Error('HTTP '+r.status);const data=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json();sourceLayers.set(layer,data);if(state.layer===layer){layerCache.delete(layer);detailKey='';render();}}catch(e){sourceErrors.set(layer,e.message);$('#error').textContent='原站层数据加载失败：'+layer+'。刷新页面可重试。';}finally{sourceRequests.delete(layer)}}
const layers=manifest.layers;let state={level:1,layer:null,group:null,neuron:null},mode=localStorage.getItem('microscope-mode')||'feature',researchHistory=[],zoom=1;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function datum(){const n=sourceLayers.get(state.layer)?.neurons[state.neuron];if(n)return normalizeNeuron(state.layer,n,sourceConnections[state.layer+':'+state.neuron]);if(state.layer===sample.layer&&state.neuron===sample.neuron)return {...sample,connections:normalizeConnections(sourceConnections[sample.layer+':'+sample.neuron])};return null}
function relations(){const d=datum();if(state.level!==4||!d?.connections)return[];return ['upstream','downstream'].flatMap(dir=>['positive','negative'].flatMap(sign=>d.connections[dir][sign].map(r=>({...r,dir,sign,layer:d.connections[dir].source_layer||d.connections[dir].target_layer,method:d.connections[dir].method}))))}
function go(next,{remember=true,scroll=false}={}){if(remember&&state.level===4&&next.level===4&&(next.layer!==state.layer||next.neuron!==state.neuron))researchHistory.push({...state});state={...state,...next};hideTip();render();const p=new URLSearchParams();p.set('level',state.level);if(state.layer)p.set('layer',state.layer);if(state.group!==null)p.set('group',state.group);if(state.level===4)p.set('neuron',state.neuron);history.replaceState(null,'',`#${p}`);if(scroll)$('#workspace').scrollIntoView({behavior:'smooth',block:'start'})}
function openNeuron(layer,n){go({level:4,layer,group:Math.floor(n/16),neuron:n},{scroll:true})}
function placeholder(dataset=false){return `<div class="placeholder ${dataset?'dataset':''}" aria-label="图片待导入">${dataset?'<span>待导入</span>'.repeat(4):'图片待导入'}</div>`}
const variantNames=['Positive','Path-guided positive','Diversity 2×2','Negative','Path-guided negative'];
function sourceAsset(path){return 'source/'+(sourceIndex.asset_paths?.[path]||path)}
function rawNeuron(layer,n){return sourceLayers.get(layer)?.neurons[n]}
function sourceImage(path,label){return `<div class="source-image-wrap"><img class="source-image" src="${sourceAsset(path)}" alt="${esc(label)}" loading="lazy" decoding="async"></div>`}
function imageState(text){return `<div class="placeholder image-state">${text}</div>`}
function neuronPreview(layer,n,view){const raw=rawNeuron(layer,n),sheet=`thumbs/${layer}/${n}.jpg`,fv=`fv/positive/${layer}/${n}.png`;if(view==='dataset'){if(raw?.hid)return imageState('原站已隐藏');const full=`sheets/${layer}/${n}.jpg`;return assetSet.has(full)?`<div class="source-image-wrap dataset-preview">${[0,1,2,3].map(cell=>(raw?.hx||[]).includes(cell)?imageState('原站已隐藏'):`<div class="sheet-crop" style="background-image:url('${sourceAsset(full)}');background-size:1600% 300%;background-position:${cell*100/15}% 0%" role="img" aria-label="${layer}:${n} Dataset ${cell+1}"></div>`).join('')}</div>`:placeholder(true);}if(raw?.fv?.[0]==='h')return imageState('原站已隐藏');return assetSet.has(fv)?sourceImage(fv,`${layer}:${n} Positive Feature Vis`):placeholder();}
function featureVariants(d){return `<div class="variants">${sourceMeta.fvSlots.map((slot,i)=>{const status=d?.raw?.fv?.[i],path=`fv/${slot}/${state.layer}/${state.neuron}.png`;return `<div class="variant">${status==='h'?imageState('原站已隐藏'):status==='0'?imageState('原站未生成'):assetSet.has(path)?`<a href="${sourceAsset(path)}" target="_blank" rel="noreferrer">${sourceImage(path,variantNames[i])}</a>`:placeholder()}<p>${variantNames[i]}</p></div>`;}).join('')}</div>`;}
function exampleBucket(d,index){const bucket=sourceMeta.buckets[index],rows=d?.raw?.b?.[index];if(!rows)return '<div class="missing">样例元数据正在加载</div>';if(d.raw.hid)return '<div class="missing">原站已隐藏此神经元的自然图像样例</div>';const offset=sourceMeta.buckets.slice(0,index).reduce((sum,b)=>sum+b.count,0),hidden=new Set(d.raw.hx||[]),sheet=`sheets/${state.layer}/${state.neuron}.jpg`,available=assetSet.has(sheet);return `<div class="example-bucket"><h4>${esc(bucket.label)}</h4>${index===0?`<p class="source-note">网页裁剪图为 64×64 像素 · <a href="${sourceIndex.source}sheets/${state.layer}/${state.neuron}.jpg" target="_blank" rel="noreferrer">查看原站原尺寸拼图 ↗</a></p>`:""}${index===0&&d.top60_classes.length?`<p class="class-summary">原站 Top-60 类别摘要：${d.top60_classes.map(c=>`<span>${esc(c.label)} × ${c.count}</span>`).join('')}</p>`:''}<div class="example-grid">${rows.map(([id,label,value,rank],j)=>{const cell=offset+j,x=cell%16,y=Math.floor(cell/16);const image=hidden.has(cell)?imageState('原站已隐藏'):available?`<div class="sheet-crop" role="img" ${cell<32?`data-heat-cell="${cell}"`:""} aria-label="${esc(label)}" style="background-image:url('${sourceAsset(sheet)}');background-size:1600% 300%;background-position:${x*100/15}% ${y*50}%"></div>`:imageState('图片待导入');return `<figure>${image}<figcaption><b>#${rank} · ${value}</b><span>${esc(label)}</span><small>ImageNet ${id}</small></figcaption></figure>`;}).join('')}</div></div>`;}
function groupMarkup(l,g,expanded,rel){if(expanded)return `<div class="group active-group" data-group="${g.group_index}"><span class="range">GROUP ${String(g.group_index+1).padStart(2,'0')} / ${g.range_label}</span><div class="mode"><button data-mode="feature" class="${mode==='feature'?'on':''}">Feature Vis</button><button data-mode="dataset" class="${mode==='dataset'?'on':''}">Dataset</button></div>${g.cells_row_major.filter(n=>n!==null).map(n=>`<button class="neuron ${state.level===4&&state.neuron===n?'selected':''}" data-node="${l.name}:${n}" aria-label="打开 ${l.name}:${n}">${neuronPreview(l.name,n,mode)}<div><b>${String(n).padStart(3,'0')}</b><small>${mode==='dataset'?'TOP 4 · DATASET':'FEATURE VIS'}</small>${l.name===sample.layer&&n===sample.neuron?'<small style="color:#27877d">● 真实图片及关系</small>':''}</div></button>`).join('')}</div>`;
return `<div class="group" data-group="${g.group_index}"><span class="range">${g.range_label}</span><div class="grid" ${state.level===1?'':`role="group" aria-label="${l.name} ${g.range_label}"`}>${g.cells_row_major.map(n=>{if(n===null)return '<span class="cell empty" aria-hidden="true"></span>';const r=rel.find(r=>r.layer===l.name&&r.neuron===n);const peak=r&&Math.abs(r.value)===Math.max(...rel.filter(a=>a.dir===r.dir&&a.sign===r.sign).map(a=>Math.abs(a.value)));let style='';if(r){const max=Math.max(...rel.filter(a=>a.dir===r.dir).map(a=>Math.abs(a.value)));const alpha=.55+.45*Math.abs(r.value)/max;style=`background:rgba(${r.sign==='positive'?'39,135,125':'198,107,75'},${alpha});color:${r.sign==='positive'?'#1c695f':'#95472e'}`;}return `<button class="cell ${r?'relation'+(peak?' peak':''):''}" style="${style}" data-cell="${l.name}:${n}" aria-label="${l.name}:${n}${r?' '+(r.value>0?'+':'')+r.value+(peak?'，该方向同符号已知关系中绝对值最大':''):'，关系数据未知'}" title="${l.name}:${n}${r?' · '+r.value:' · 待导入'}">${n}</button>`}).join('')}</div></div>`}
const layerCache=new Map();let detailKey='';
function overviewGeometry(count,adjacent=false){
 const columns=adjacent?(count>32?4:count>12?3:2):(count>40?3:count>12?2:1);
 const rows=Math.ceil(count/columns),gap=adjacent?8:6,available=adjacent?648:548,width=adjacent?182:78;
 const mini=Math.min(adjacent?60:34,Math.floor((available-gap*(rows-1))/rows),Math.floor((width-gap*(columns-1))/columns));
 return {columns,mini};
}

function render(){document.querySelectorAll('.layer').forEach(el=>el.getAnimations().forEach(a=>a.cancel()));const previousRects=new Map([...document.querySelectorAll('[data-layer-section]')].map(el=>[el.dataset.layerSection,el.getBoundingClientRect()]));const idx=layers.findIndex(l=>l.name===state.layer),rel=relations();$('#breadcrumbs').innerHTML=`<span class="level">LEVEL 0${state.level}</span><button data-home>全网络</button>${state.layer?`<span>/</span><button data-layer="${state.layer}">${state.layer}</button>`:''}${state.level>=3?`<span>/</span><span>${layers[idx].groups[state.group].range_label}</span>`:''}${state.level===4?`<span>/</span><b>${state.neuron}</b>`:''}`;
$('#back').disabled=state.level===1;$('#history').disabled=!researchHistory.length;$('#hint').textContent=['','点击圆角框内任意位置展开','点击 4×4 网格展开','点击神经元查看详情','悬停彩色节点查看关系，点击切换研究中心'][state.level];
const network=$('#network');
$('#viewport').classList.toggle('research-view',state.level===4);
if(!network.querySelector('[data-layer-section]'))network.innerHTML='<div class="endpoint"><div class="symbol">▧</div>INPUT</div>'+layers.map(l=>`<section data-layer-section="${l.name}"></section>`).join('')+'<div class="endpoint"><div class="symbol">≋</div>OUTPUT</div>';
const changed=[];
layers.forEach((l,i)=>{
 const focus=l.name===state.layer,adj=state.level===4&&Math.abs(i-idx)===1,overview=!focus;
 const {columns,mini}=overviewGeometry(l.group_count,adj);
 const el=network.querySelector(`[data-layer-section="${l.name}"]`);
 const signature=[focus,adj,focus?state.level:0,focus?state.group:'',focus?state.neuron:'',focus?mode:'',adj?state.layer+':'+state.neuron:''].join('|');
 el.className=`layer ${focus?'focus':''} ${focus&&state.level>=3?'expanded':''} ${adj?'adjacent':''} ${overview?'overview':''}`;
 el.style.cssText=`--mini:${mini}px;--columns:${columns}`;
 el.setAttribute('aria-label',`${l.name}，${l.channel_count} 个神经元`);
 if(layerCache.get(l.name)===signature)return;
 el.innerHTML=`<button class="layer-head" data-layer="${l.name}" title="${l.name} · ${l.channel_count} 个神经元">${l.name}<small>${l.channel_count} neurons${adj?' · '+(i<idx?'上游':'下游'):''}</small></button><div class="layer-body"><div class="group-stack">${l.groups.map(g=>groupMarkup(l,g,focus&&state.level>=3&&g.group_index===state.group,rel)).join('')}</div></div><span class="layer-caption">${focus?'EXPLORING':adj?'TOP 4 · '+(rel.length?'有符号归因':'数据待导入'):'点击展开 ↗'}</span>`;
 layerCache.set(l.name,signature);changed.push(el);
});
$('#network').style.zoom=zoom;$('#status').textContent=state.level===1?'12 个观测层 · 按编号排列 · 点击逐级展开':`${state.layer} · ${layers[idx].channel_count} 个神经元${state.level===4?' · Top 4 着色 · 双边框标记同方向、同符号已知关系中的最大值':''}`;
const nextDetailKey=state.level===4?state.layer+':'+state.neuron:'';if(detailKey!==nextDetailKey){renderDetails();detailKey=nextDetailKey;}$('#mininav').innerHTML=`<button data-return>↑ 返回画布</button>${layers.map(l=>`<button data-layer="${l.name}" class="${l.name===state.layer?'current':''}">${l.name}${l.name===state.layer&&state.level===4?':'+state.neuron:''}</button>`).join('')}`;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(state.level>=3){const body=$('.layer.focus .layer-body'),target=state.level===4?$('.neuron.selected'):$('.active-group');body.scrollTop+=(target.getBoundingClientRect().top-body.getBoundingClientRect().top)/zoom-(state.level===4?body.clientHeight/2-target.clientHeight/2:12);}
if(state.layer){const focus=$('.layer.focus'),vp=$('#viewport'),a=focus.getBoundingClientRect(),b=vp.getBoundingClientRect();vp.scrollLeft=Math.max(0,vp.scrollLeft+a.left-b.left-vp.clientWidth/2+a.width/2);}
// One final layout read, followed by compositor-only animation writes.
const finalRects=[...document.querySelectorAll('[data-layer-section]')].map(el=>({el,rect:el.getBoundingClientRect(),old:previousRects.get(el.dataset.layerSection)}));
if(!reduced&&previousRects.size){
 finalRects.forEach(({el,rect,old})=>{if(!old||!rect.width||!rect.height)return;const dx=(old.left-rect.left)/zoom,dy=(old.top-rect.top)/zoom,sx=old.width/rect.width,sy=old.height/rect.height;if(Math.abs(dx)+Math.abs(dy)+Math.abs(1-sx)+Math.abs(1-sy)<.1)return;el.animate([{transform:`translate(${dx}px,${dy}px) scale(${sx},${sy})`},{transform:'none'}],{duration:440,easing:'cubic-bezier(.22,1,.36,1)'});});
 changed.filter(el=>el.classList.contains('focus')||el.classList.contains('adjacent')).forEach(el=>{el.querySelector('.group-stack').animate([{opacity:.15},{opacity:1}],{duration:300,delay:90,fill:'backwards'});const controls=el.querySelector('.mode');if(controls)controls.animate([{opacity:0,transform:'translateY(5px)'},{opacity:1,transform:'none'}],{duration:240,delay:140,fill:'backwards'});});
}
updateMini();ensureSourceLayer(state.layer);
}

const statNames={maximum:'最大激活',p99_99:'99.99% 分位点',p99_9:'99.9% 分位点',p99:'99% 分位点',median:'中位数',active_image_percent:'活跃图片比例',pre_relu_minimum:'Pre-ReLU 最小值',pre_relu_p0_1:'Pre-ReLU 0.1% 分位点',mean:'图像最大响应均值',std:'图像最大响应标准差',pre_relu_p1:'Pre-ReLU 1% 分位点',pre_relu_mean:'图像最小响应均值'};
function section(n,title,content){return `<section class="detail-section"><div class="section-title"><span>${n}</span><h3>${title}</h3></div>${content}</section>`}
function connectionSide(dir){const index=layers.findIndex(l=>l.name===state.layer),neighbor=layers[index+(dir==='upstream'?-1:1)],d=datum(),title=dir==='upstream'?'上游 · Gradient × Activation':'下游 · Zero-ablation';if(!neighbor)return `<div class="connection-side"><h4>${title}</h4><div class="missing">网络结构边界 · 不存在${dir==='upstream'?'前':'后'}一观测层</div></div>`;return `<div class="connection-side"><h4>${title}</h4><p>${neighbor.name} ${dir==='upstream'?'→ '+state.layer: '← '+state.layer}</p>${d?.connections?['positive','negative'].map(sign=>`<h5 class="${sign}">${sign==='positive'?'Strongest Positive':'Strongest Negative'} · 4</h5>${d.connections[dir][sign].map(r=>`<button class="connection-row" data-connection="${neighbor.name}:${r.neuron}"><span>${neighbor.name}:${r.neuron} ↗</span><small>${r.sample_count}/${r.example_count||60}</small><span class="value ${sign}">${r.value>0?'+':''}${r.value}</span></button>`).join('')}`).join(''):'<div class="missing">该神经元的关系数据待导入</div>'}</div>`}
function renderDetails(){if(state.level!==4){$('#details').innerHTML='';return}const d=datum();$('#details').innerHTML=`<div class="detail-heading"><div><div class="eyebrow">NEURON OVERVIEW</div><h2>${state.layer} <span style="color:#a1aca0">/</span> ${String(state.neuron).padStart(3,'0')}</h2><p>${d?.source_verified?'原站结构化数据 · 图片按导入状态展示':d?'已核查文字样例 · 正在加载原始数据':'正在加载原站层数据'}</p></div><a class="source-note" href="https://already-clean.goodfire.com/microscope/inceptionv1.html?layer=${state.layer}&neuron=${state.neuron}" target="_blank" rel="noreferrer">在原始 Microscope 查看 ↗</a></div>`+section('01','Activation Statistics',d?`<div class="stats">${Object.entries(d.activation_statistics).map(([k,v])=>`<div class="stat"><span>${statNames[k]}</span><b>${v.toLocaleString('zh-CN',{maximumFractionDigits:3})}${k==='active_image_percent'?'%':''}</b></div>`).join('')}</div><p class="source-note">数值直接来自原站 JSON，保留原始精度；未取得完整分布序列，因此不由分位点推造曲线。</p>`:'<div class="missing">激活统计与分布数据待导入</div>')+section('02','Feature Visualization',featureVariants(d))+section('03','Dataset Examples',`<button class="heat-toggle" id="heat-toggle" aria-pressed="false">显示激活热图</button><span id="heat-status" class="source-note"></span>`+exampleBucket(d,0))+section('04','Additional Examples',[1,2,3].map(i=>exampleBucket(d,i)).join(''))+section('05','Neuron Connections',`<p class="source-note">上下游使用不同指标，颜色分别归一化。保留原站展示顺序；x/60 表示在 60 张样例中保持该符号的数量。悬停可在画布定位，点击切换研究中心。</p><div class="connection-columns">${connectionSide('upstream')}${connectionSide('downstream')}</div>`)+`<p class="source-note">来源：Goodfire Microscope，2026-10-23 直接下载。${d?.source_verified?'统计、类别和样例元数据直接来自原站 JSON；图片只展示已下载且原站未隐藏的资源。':'层数据正在加载。'}</p>`}
function hideTip(){$('#tooltip').hidden=true;$('#lines').innerHTML='';document.querySelectorAll('.linked-hover').forEach(x=>x.classList.remove('linked-hover'))}
function showRelation(key,anchor,touch=false){const r=relations().find(r=>`${r.layer}:${r.neuron}`===key);if(!r)return;hideTip();const cell=document.querySelector(`[data-cell="${key}"]`),center=$('.neuron.selected');if(!cell||!center)return;const body=cell.closest('.layer-body');if(!cell.closest('.overview'))body.scrollTop+=cell.getBoundingClientRect().top-body.getBoundingClientRect().top-body.clientHeight/2;cell.classList.add('linked-hover');const vp=$('#viewport'),a=cell.getBoundingClientRect(),b=center.getBoundingClientRect(),v=vp.getBoundingClientRect();const sx=a.left+a.width/2-v.left+vp.scrollLeft,sy=a.top+a.height/2-v.top+vp.scrollTop,ex=b.left+b.width/2-v.left+vp.scrollLeft,ey=b.top+b.height/2-v.top+vp.scrollTop;$('#lines').innerHTML=`<path d="M${sx},${sy} C${(sx+ex)/2},${sy} ${(sx+ex)/2},${ey} ${ex},${ey}" fill="none" stroke="${r.sign==='positive'?'#27877d':'#c66b4b'}" stroke-width="2" stroke-dasharray="4 3"/>`;const tip=$('#tooltip');tip.innerHTML=`<b>${key}</b><br>${r.dir==='upstream'?'上游 · Gradient × Activation':'下游 · Zero-ablation'}<br>数值 ${r.value>0?'+':''}${r.value} · 样例 ${r.sample_count}/${r.example_count||60}${touch?`<button data-enter="${key}">进入此神经元 ↗</button>`:''}`;tip.hidden=false;const ar=anchor.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(ar.left,innerWidth-300))+'px';tip.style.top=Math.max(8,Math.min(ar.bottom+8,innerHeight-tip.offsetHeight-8))+'px'}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t){const card=e.target.closest('[data-layer-section]');if(!card)return;const layer=card.dataset.layerSection;if(layer!==state.layer||state.level===1)return go({level:2,layer,group:null,neuron:null},{scroll:true});const group=e.target.closest('[data-group]');if(group&&!group.classList.contains('active-group'))return go({level:3,group:+group.dataset.group,neuron:null});return;}if(t.id==='heat-toggle')return toggleHeatmaps(t);if(t.hasAttribute('data-home'))return go({level:1,layer:null,group:null,neuron:null});if(t.dataset.layer&&t.closest('[data-layer-section]')&&t.dataset.layer===state.layer)return;if(t.dataset.layer)return go({level:2,layer:t.dataset.layer,group:null,neuron:null},{scroll:true});if(t.dataset.mode){mode=t.dataset.mode;localStorage.setItem('microscope-mode',mode);const body=$('.layer.focus .layer-body'),top=body.scrollTop;render();requestAnimationFrame(()=>{$('.layer.focus .layer-body').scrollTop=top});return}const key=t.dataset.node||t.dataset.connection||t.dataset.enter;if(key){const [l,n]=key.split(':');return openNeuron(l,+n)}if(t.dataset.cell){const[l,n]=t.dataset.cell.split(':');const i=layers.findIndex(x=>x.name===l),current=layers.findIndex(x=>x.name===state.layer);if(state.level===4&&Math.abs(i-current)===1){if(matchMedia('(pointer: coarse)').matches&&relations().some(r=>r.layer===l&&r.neuron===+n))return showRelation(t.dataset.cell,t,true);return openNeuron(l,+n)}if(l!==state.layer||state.level===1)return go({level:2,layer:l,group:null,neuron:null});return go({level:3,layer:l,group:Math.floor(+n/16),neuron:null})}if(t.hasAttribute('data-return'))$('#workspace').scrollIntoView({behavior:'smooth'})});
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const t=e.target.closest('[data-cell],[data-connection]');if(t)showRelation(t.dataset.cell||t.dataset.connection,t)});document.addEventListener('pointerout',e=>{if(e.pointerType==='touch')return;const t=e.target.closest('[data-cell],[data-connection]');if(t&&!t.contains(e.relatedTarget))hideTip()});document.addEventListener('focusin',e=>{const t=e.target.closest('[data-cell],[data-connection]');if(t)showRelation(t.dataset.cell||t.dataset.connection,t)});document.addEventListener('focusout',hideTip);
$('#back').onclick=()=>{if(state.level===4)go({level:3,neuron:null});else if(state.level===3)go({level:2,group:null,neuron:null});else if(state.level===2)go({level:1,layer:null,group:null,neuron:null})};$('#history').onclick=()=>{if(researchHistory.length)go(researchHistory.pop(),{remember:false,scroll:true})};$('#sample').onclick=()=>openNeuron(sample.layer,sample.neuron);$('#search').onsubmit=e=>{e.preventDefault();const raw=$('#locator').value.trim(),m=raw.match(/^([a-z0-9]+)\s*[:：]\s*(\d+)$/i),l=m&&layers.find(l=>l.name===m[1].toLowerCase());if(!l||+m[2]>=l.channel_count){$('#error').textContent='请输入有效的 层名称:编号，例如 mixed4c:327。编号从 0 开始。';return}$('#error').textContent='';openNeuron(l.name,+m[2])};$('#zoom').onchange=e=>{zoom=+e.target.value;$('#network').style.zoom=zoom;hideTip()};$('#coverage').onclick=()=>$('#data-dialog').showModal();$('#close-dialog').onclick=()=>$('#data-dialog').close();function updateMini(){$('#mininav').classList.toggle('visible',state.level===4&&$('#workspace').getBoundingClientRect().bottom<0)}window.addEventListener('scroll',()=>{updateMini();hideTip()},{passive:true});window.addEventListener('resize',hideTip);$('#viewport').addEventListener('scroll',hideTip,{passive:true});document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip()});
const p=new URLSearchParams(location.hash.slice(1)),l=layers.find(l=>l.name===p.get('layer')),lev=+p.get('level'),n=+p.get('neuron'),g=+p.get('group');if(l&&lev>=2&&lev<=4){if(lev===2)state={level:2,layer:l.name,group:null,neuron:null};else if(lev===4&&p.has('neuron')&&Number.isInteger(n)&&n>=0&&n<l.channel_count)state={level:4,layer:l.name,group:Math.floor(n/16),neuron:n};else if(lev===3&&Number.isInteger(g)&&g>=0&&g<l.group_count)state={level:3,layer:l.name,group:g,neuron:null}}render();

document.addEventListener('error',e=>{if(e.target.matches?.('img.source-image')){const box=e.target.parentElement;box.classList.add('image-failed');e.target.hidden=true;box.setAttribute('aria-label','图片加载失败');} },true);

async function toggleHeatmaps(button){
 const channel=state.neuron,key=state.layer+':'+state.neuron,path=`heat/${state.layer}/${state.neuron}.bin`,status=$('#heat-status');
 if(button.getAttribute('aria-pressed')==='true'){document.querySelectorAll('.sheet-crop canvas').forEach(c=>c.remove());button.setAttribute('aria-pressed','false');button.textContent='显示激活热图';status.textContent='';return;}
 if(!assetSet.has(path)){status.textContent=rawNeuron(state.layer,state.neuron)?.hid?'原站已隐藏此神经元样例':'热图文件不可用';return;}
 button.disabled=true;status.textContent='加载中…';
 try{const response=await fetch(sourceAsset(path));if(!response.ok)throw Error();const size=sourceMeta.heatmaps.size,stride=size*size*sourceMeta.heatmaps.mapsPerNeuron;let bytes;if(sourceIndex.heat_storage==='layer_gzip'){const all=new Uint8Array(await new Response(response.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());bytes=all.subarray(channel*stride,(channel+1)*stride);}else bytes=new Uint8Array(await response.arrayBuffer());
 if(bytes.length!==size*size*sourceMeta.heatmaps.mapsPerNeuron)throw Error();
 if(key!==state.layer+':'+state.neuron||!button.isConnected)return;
 document.querySelectorAll('.sheet-crop[data-heat-cell]').forEach(el=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=size;canvas.setAttribute('aria-hidden','true');const ctx=canvas.getContext('2d'),img=ctx.createImageData(size,size),start=Number(el.dataset.heatCell)*size*size;for(let i=0;i<size*size;i++){const v=bytes[start+i]/255;img.data[4*i]=255;img.data[4*i+1]=Math.round(190*(1-v));img.data[4*i+2]=20;img.data[4*i+3]=Math.round(185*v);}ctx.putImageData(img,0,0);el.append(canvas);});
 button.setAttribute('aria-pressed','true');button.textContent='隐藏激活热图';status.textContent='每张裁剪图独立归一化；仅覆盖前 32 张正激活样例。';
 }catch{if(button.isConnected)status.textContent='热图加载失败，请重试。';}finally{button.disabled=false;}
}
